class SecurityIo(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    io_input_file: Annotated[
        PathAbsolute | None,
        Field(
            description='Path to the input file. Automatically grants read tool and read permission to this file. Validated against the path blocklist.\nAbsolute filesystem path starting with / — excludes traversal and sensitive path patterns. The resolved form after absolutization.',
            title='IoInputFileAbs',
        ),
    ] = None
    io_input_directory: Annotated[
        PathAbsolute | None,
        Field(
            description='Path to the input directory. Automatically grants read tool and read permission to this directory. Validated against the path blocklist.\nAbsolute filesystem path starting with / — excludes traversal and sensitive path patterns. The resolved form after absolutization.',
            title='IoInputDirectoryAbs',
        ),
    ] = None
    io_input_tempdir: Annotated[
        IoInputTempdir | None,
        Field(
            description='Opaque directory name (a short slug, not a path) for this agent type\'s temp staging area. The dispatcher writes input data to /tmp/{workspace}/{value}/ and the agent auto-derives read access to that scoped path. Provide only the name segment — e.g., "cobalt-stage", not "/tmp/myworkspace/cobalt-stage". The format transformer may hash both workspace and value for obfuscation on disk. Must not be derived from the agent name or reveal agent structure — if names follow a predictable pattern, an adversarial LLM can enumerate temp directories for other agent types. Choose an arbitrary, non-descriptive name per agent type. Examples: "cobalt-stage", "theta-7" (good); "embedding- normalizer-input", "input" (bad — reveals agent identity or is too predictable).\nLowercase kebab-case string — words separated by hyphens. Used for identifiers that must be URL-safe and filesystem-safe.',
            title='IoInputTempdir',
        ),
    ] = None
    io_scratch_tempdir: Annotated[
        IoScratchTempdir | None,
        Field(
            description='Opaque directory name (a short slug, not a path) for this agent type\'s scratch/intermediate file area. The agent auto-derives write access to /tmp/{workspace}/{value}/ for intermediate processing files. Provide only the name segment — e.g., "cedar-scratch", not "/tmp/myworkspace/cedar- scratch". The format transformer may hash both workspace and value for obfuscation on disk. Same opaque naming rules as security_io_input_tempdir — must not be derived from the agent name or reveal agent structure. Examples: "cedar-scratch", "work-bravo" (good); "my-agent-work" (bad — reveals agent identity).\nLowercase kebab-case string — words separated by hyphens. Used for identifiers that must be URL-safe and filesystem-safe.',
            title='IoScratchTempdir',
        ),
    ] = None
    io_output_file: Annotated[
        PathAbsolute | None,
        Field(
            description='Workspace-relative path to the agent\'s output file. The security resolver uses this path to create a constrained write tool that enforces schema validation, format checking, and batch size limits on every write. This path must NOT appear in security_paths_allowed_write — if it did, the agent would have a second, unconstrained write path bypassing all enforcement. Validated against the path blocklist. Example: "interview/output/results.jsonl"\nAbsolute filesystem path starting with / — excludes traversal and sensitive path patterns. The resolved form after absolutization.',
            title='IoOutputFileAbs',
        ),
    ] = None
    io_output_directory: Annotated[
        PathAbsolute | None,
        Field(
            description='Workspace-relative path to the agent\'s output directory. The security resolver uses this to create a constrained write tool that enforces schema validation, format checking, and batch size limits on every write within this directory. This path must NOT appear in security_paths_allowed_write — if it did, the agent would have unconstrained write access bypassing all enforcement. Validated against the path blocklist. Example: "interview/output/"\nAbsolute filesystem path starting with / — excludes traversal and sensitive path patterns. The resolved form after absolutization.',
            title='IoOutputDirectoryAbs',
        ),
    ] = None


class SecuritySchema(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    input_schema: Annotated[
        PathExistsAbsolute | None,
        Field(
            description='Schema the input data validates against. Workspace-relative path to a .schema.json or .schema.yaml file. The resolver uses this for input validation enforcement — a security property.\nAbsolute path that must exist on the filesystem',
            title='InputSchemaXAbs',
        ),
    ] = None
    output_schema: Annotated[
        PathExistsAbsolute | None,
        Field(
            description='Schema the output data must validate against. Workspace-relative path to a .schema.json file. Lives in the security section because the resolver needs it for engineering control derivation — schema validation is a security enforcement property.\nAbsolute path that must exist on the filesystem',
            title='OutputSchemaXAbs',
        ),
    ] = None
    return_schema: Annotated[
        PathExistsAbsolute | None,
        Field(
            description='Absolute path to a JSON Schema file (must end with .schema.json or .schema.yaml) defining the metric fields the agent returns. Always embedded directly into the prompt — there is no enforcement mechanism for return communication (agent-to-dispatcher LLM text). Embedding ensures the agent sees field names, types, and definitions. Schema file must exist at resolution time. Example: "definitions/schemas/my-agent-return.schema.json"\nAbsolute path that must exist on the filesystem',
            title='ReturnSchemaXAbs',
        ),
    ] = None
    output_schema_embed: Annotated[
        Boolean | None,
        Field(
            description='Whether to embed the output schema directly into the agent prompt. When true, the format transformer reads the schema file and inlines its content — uses context window but ensures the agent sees the schema without a tool call. When false (or omitted), the schema path is granted read access and the agent reads it via Read tool — saves context but adds a tool-call round trip. Prefer true for small schemas (under ~100 lines) or when schema adherence is critical. Prefer false for large schemas where context window conservation matters. Either way the agent knows the desired shape.\nTrue or false value',
            title='OutputSchemaEmbed',
        ),
    ] = None


